
.vipcard {
  border-radius: 20px;
  padding: 10px 0;
  margin: 0 10px 10px;
  border-left: 5px solid #db7e42;
  border-right: 5px solid #db7e42;
  .q-card__section--vert {
    padding: 0;
    > div {
      flex: 1;
    }
  }
  .q-card__actions .q-btn {
    min-width: 60px;
  }

  .top-section {
    display: flex;
    flex-direction: column;
    gap: 10px;
    justify-content: center;
    align-items: center;
    padding: 10px 0;
    img {
      max-width: 80px;
      margin: 0 auto;
      display: block;
    }
  }

  .bot-section {
    background: #212534;
    display: flex;
    justify-content: space-around;
    .acct-section {
      display: flex;
      flex-direction: column;
      text-align: center;
      justify-content: space-evenly;
      .q-seperator--dark {
        border-right: 1px solid #ffffff;
      }
    }
    .q-btn__content {
      font-size: 12px;
      display: flex;
      flex-direction: column;
      svg {
        fill: #ffffff;
        width: 25px;
        display: block;
        padding: 0;
      }
    }
  }
}
.acct-nav {
  gap: 10px;
  margin-bottom: 20px;
  .acct-nav-item {
    cursor: pointer;
    display: flex;
    padding: 20px;
    justify-content: flex-start;
    align-items: center;
    gap: 10px;
    border-radius: 10px;
    margin: 0 10px;

    svg {
      width: 30px;
      fill: white;
      padding: 0;
    }
  }
}
